79	/*
80	 * Enables advertising with parameters:
81	 *     o General discoverable mode
82	 *     o Undirected connectable mode
83	 */
84	static void
85	blecsc_advertise(void)
86	{
87	
88	    struct ble_gap_adv_params adv_params;
89	    struct ble_hs_adv_fields fields;
90	    int rc;
91	
92	    /*
93	     *  Set the advertisement data included in our advertisements:
94	     *     o Flags (indicates advertisement type and other general info)
95	     *     o Advertising tx power
96	     *     o Device name
97	     */
98	    memset(&fields, 0, sizeof(fields));
99	
100	    /*
101	     * Advertise two flags:
102	     *      o Discoverability in forthcoming advertisement (general)
103	     *      o BLE-only (BR/EDR unsupported)
104	     */
105	    fields.flags = BLE_HS_ADV_F_DISC_GEN |
106	                   BLE_HS_ADV_F_BREDR_UNSUP;
107	
108	    /*
109	     * Indicate that the TX power level field should be included; have the
110	     * stack fill this value automatically.  This is done by assigning the
111	     * special value BLE_HS_ADV_TX_PWR_LVL_AUTO.
112	     */
113	    fields.tx_pwr_lvl_is_present = 1;
114	    fields.tx_pwr_lvl = BLE_HS_ADV_TX_PWR_LVL_AUTO;
115	
116	    fields.name = (uint8_t *)device_name;
117	    fields.name_len = strlen(device_name);
118	    fields.name_is_complete = 1;
119	
120	    /*
121	     * Set appearance.
122	     */
123	    fields.appearance = ble_svc_gap_device_appearance();
124	    fields.appearance_is_present = 1;
125	
126	    rc = ble_gap_adv_set_fields(&fields);
127	    if (rc != 0) {
128	        MODLOG_DFLT(ERROR, "error setting advertisement data; rc=%d\n", rc);
129	        return;
130	    }
131	
132	    /* Begin advertising */
133	    memset(&adv_params, 0, sizeof(adv_params));
134	    adv_params.conn_mode = BLE_GAP_CONN_MODE_UND;
135	    adv_params.disc_mode = BLE_GAP_DISC_MODE_GEN;
136	    rc = ble_gap_adv_start(blecsc_addr_type, NULL, BLE_HS_FOREVER,
137	                           &adv_params, blecsc_gap_event, NULL);
138	    if (rc != 0) {
139	        MODLOG_DFLT(ERROR, "error enabling advertisement; rc=%d\n", rc);
140	        return;
141	    }
142	}
