145	/* Update simulated CSC measurements.
146	 * Each call increments wheel and crank revolution counters by one and
147	 * computes last event time in order to match simulated candence and speed.
148	 * Last event time is expressedd in 1/1024th of second units.
149	 *
150	 *                 60 * 1024
151	 * crank_dt =    --------------
152	 *                cadence[RPM]
153	 *
154	 *
155	 *                circumference[mm] * 1024 * 60 * 60
156	 * wheel_dt =    -------------------------------------
157	 *                         10^6 * speed [kph]
158	 */
159	static void
160	blecsc_simulate_speed_and_cadence(void)
161	{
162	
163	    uint16_t wheel_rev_period;
164	    uint16_t crank_rev_period;
165	
166	    /* Update simulated crank and wheel rotation speed */
167	    csc_sim_speed_kph++;
168	    if (csc_sim_speed_kph >= CSC_SIM_SPEED_KPH_MAX) {
169	         csc_sim_speed_kph = CSC_SIM_SPEED_KPH_MIN;
170	    }
171	
172	    csc_sim_crank_rpm++;
173	    if (csc_sim_crank_rpm >= CSC_SIM_CRANK_RPM_MAX) {
174	         csc_sim_crank_rpm = CSC_SIM_CRANK_RPM_MIN;
175	    }
176	
177	    /* Calculate simulated measurement values */
178	    if (csc_sim_speed_kph > 0){
179	        wheel_rev_period = (36*64*CSC_SIM_WHEEL_CIRCUMFERENCE_MM) /
180	                           (625*csc_sim_speed_kph);
181	        csc_measurement_state.cumulative_wheel_rev++;
182	        csc_measurement_state.last_wheel_evt_time += wheel_rev_period;
183	    }
184	
185	    if (csc_sim_crank_rpm > 0){
186	        crank_rev_period = (60*1024) / csc_sim_crank_rpm;
187	        csc_measurement_state.cumulative_crank_rev++;
188	        csc_measurement_state.last_crank_evt_time += crank_rev_period;
189	    }
190	
191	    MODLOG_DFLT(INFO, "CSC simulated values: speed = %d kph, cadence = %d \n",
192	                csc_sim_speed_kph, csc_sim_crank_rpm);
193	}
194	
195	/* Run CSC measurement simulation and notify it to the client */
196	static void
197	blecsc_measurement(struct ble_npl_event *ev)
198	{
199	    int rc;
200	
201	    rc = ble_npl_callout_reset(&blecsc_measure_timer, portTICK_PERIOD_MS * 10);
202	    assert(rc == 0);
203	
204	    blecsc_simulate_speed_and_cadence();
205	
206	    if (notify_state) {
207	        rc = gatt_svr_chr_notify_csc_measurement(conn_handle);
208	        assert(rc == 0);
209	    }
210	}
