212	static int
213	blecsc_gap_event(struct ble_gap_event *event, void *arg)
214	{
215	    switch (event->type) {
216	    case BLE_GAP_EVENT_CONNECT:
217	        /* A new connection was established or a connection attempt failed */
218	        MODLOG_DFLT(INFO, "connection %s; status=%d\n",
219	                    event->connect.status == 0 ? "established" : "failed",
220	                    event->connect.status);
221	
222	        if (event->connect.status != 0) {
223	            /* Connection failed; resume advertising */
224	            blecsc_advertise();
225	            conn_handle = 0;
226	        }
227	        else {
228	          conn_handle = event->connect.conn_handle;
229	        }
230	        break;
231	
232	    case BLE_GAP_EVENT_DISCONNECT:
233	        MODLOG_DFLT(INFO, "disconnect; reason=%d\n", event->disconnect.reason);
234	        conn_handle = 0;
235	        /* Connection terminated; resume advertising */
236	        blecsc_advertise();
237	        break;
238	
239	    case BLE_GAP_EVENT_ADV_COMPLETE:
240	        MODLOG_DFLT(INFO, "adv complete\n");
241	        break;
242	
243	    case BLE_GAP_EVENT_SUBSCRIBE:
244	        MODLOG_DFLT(INFO, "subscribe event attr_handle=%d\n",
245	                    event->subscribe.attr_handle);
246	
247	        if (event->subscribe.attr_handle == csc_measurement_handle) {
248	            notify_state = event->subscribe.cur_notify;
249	            MODLOG_DFLT(INFO, "csc measurement notify state = %d\n",
250	                        notify_state);
251	        }
252	        else if (event->subscribe.attr_handle == csc_control_point_handle) {
253	            gatt_svr_set_cp_indicate(event->subscribe.cur_indicate);
254	            MODLOG_DFLT(INFO, "csc control point indicate state = %d\n",
255	                        event->subscribe.cur_indicate);
256	        }
257	        break;
258	
259	    case BLE_GAP_EVENT_MTU:
260	        MODLOG_DFLT(INFO, "mtu update event; conn_handle=%d mtu=%d\n",
261	                    event->mtu.conn_handle,
262	                    event->mtu.value);
263	        break;
264	
265	    }
266	
267	    return 0;
268	}
