270	static void
271	blecsc_on_sync(void)
272	{
273	    int rc;
274	
275	    /* Figure out address to use while advertising (no privacy) */
276	    rc = ble_hs_id_infer_auto(0, &blecsc_addr_type);
277	    assert(rc == 0);
278	
279	    /* Begin advertising */
280	    blecsc_advertise();
281	}
