283	void blecsc_host_task(void *param)
284	{
285	    ESP_LOGI(tag, "BLE Host Task Started");
286	    /* This function will return only when nimble_port_stop() is executed */
287	    nimble_port_run();
288	
289	    nimble_port_freertos_deinit();
290	}
291	/*
292	 * main
293	 *
294	 * The main task for the project. This function initializes the packages,
295	 * then starts serving events from default event queue.
296	 *
297	 * @return int NOTE: this function should never return!
298	 */
299	int
300	app_main(void)
301	{
302	    int rc;
303	
304		 /* Initialize NVS — it is used to store PHY calibration data */
305		 esp_err_t ret = nvs_flash_init();
306		 if (ret == ESP_ERR_NVS_NO_FREE_PAGES || ret == ESP_ERR_NVS_NEW_VERSION_FOUND) {
307		     ESP_ERROR_CHECK(nvs_flash_erase());
308		     ret = nvs_flash_init();
309		 }
310		 ESP_ERROR_CHECK(ret);
311	
312		 ret = nimble_port_init();
313		 if (ret != ESP_OK) {
314		     ESP_LOGE(tag, "Failed to init nimble %d ", ret);
315		     return -1;
316		 }
317	
318	    /* Initialize the NimBLE host configuration */
319	    ble_hs_cfg.sync_cb = blecsc_on_sync;
320	
321	    /* Initialize measurement and notification timer */
322	    ble_npl_callout_init(&blecsc_measure_timer, nimble_port_get_dflt_eventq(),
323	                    blecsc_measurement, NULL);
324	    rc = ble_npl_callout_reset(&blecsc_measure_timer, portTICK_PERIOD_MS * 100);
325	    assert(rc == 0);
326	
327	    rc = gatt_svr_init(&csc_measurement_state);
328	    assert(rc == 0);
329	
330	    /* Set the default device name */
331	    rc = ble_svc_gap_device_name_set(device_name);
332	    assert(rc == 0);
333	
334	    nimble_port_freertos_init(blecsc_host_task);
335	
336	    return 0;
337	}
