166	static int
167	gatt_svr_chr_access_sc_control_point(uint16_t conn_handle,
168	                                     uint16_t attr_handle,
169	                                     struct ble_gatt_access_ctxt *ctxt,
170	                                     void *arg)
171	{
172	    uint8_t op_code;
173	    uint8_t new_sensor_location;
174	    uint8_t new_cumulative_wheel_rev_arr[4];
175	    struct os_mbuf *om_indication;
176	    uint8_t response = SC_CP_RESPONSE_OP_NOT_SUPPORTED;
177	    int ii;
178	    int rc;
179	
180	    assert(ctxt->op == BLE_GATT_ACCESS_OP_WRITE_CHR);
181	
182	    if (!csc_cp_indication_status) {
183	        return CSC_ERR_CCC_DESC_IMPROPERLY_CONFIGURED;
184	    }
185	
186	    /* Read control point op code*/
187	    rc = os_mbuf_copydata(ctxt->om, 0, sizeof(op_code), &op_code);
188	    if (rc != 0){
189	        return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
190	    }
191	
192	    /* Allocate response buffer */
193	    om_indication = ble_hs_mbuf_att_pkt();
194	
195	    switch(op_code){
196	#if (CSC_FEATURES & CSC_FEATURE_WHEEL_REV_DATA)
197	    case SC_CP_OP_SET_CUMULATIVE_VALUE:
198	        /* Read new cumulative wheel revolutions value*/
199	        rc = os_mbuf_copydata(ctxt->om, 1,
200	                              sizeof(new_cumulative_wheel_rev_arr),
201	                              new_cumulative_wheel_rev_arr);
202	        if (rc != 0){
203	            return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
204	        }
205	
206	        measurement_state->cumulative_wheel_rev =
207	                           get_le32(new_cumulative_wheel_rev_arr);
208	
209	
210	        response = SC_CP_RESPONSE_SUCCESS;
211	        break;
212	#endif
213	
214	#if (CSC_FEATURES & CSC_FEATURE_MULTIPLE_SENSOR_LOC)
215	    case SC_CP_OP_UPDATE_SENSOR_LOCATION:
216	        /* Read new sensor location value*/
217	        rc = os_mbuf_copydata(ctxt->om, 1, 1, &new_sensor_location);
218	        if (rc != 0){
219	          return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
220	        }
221	
222	
223	        /* Verify if requested new location is on supported locations list */
224	        response = SC_CP_RESPONSE_INVALID_PARAM;
225	        for (ii = 0; ii < sizeof(csc_supported_sensor_locations); ii++){
226	            if (new_sensor_location == csc_supported_sensor_locations[ii]){
227	                sensor_location = new_sensor_location;
228	                response = SC_CP_RESPONSE_SUCCESS;
229	                break;
230	            }
231	        }
232	        break;
233	
234	    case SC_CP_OP_REQ_SUPPORTED_SENSOR_LOCATIONS:
235	        response = SC_CP_RESPONSE_SUCCESS;
236	        break;
237	#endif
238	
239	    default:
240	        break;
241	    }
242	
243	    /* Append response value */
244	    rc = os_mbuf_append(om_indication, &response, sizeof(response));
245	
246	    if (rc != 0){
247	      return BLE_ATT_ERR_INSUFFICIENT_RES;
248	    }
249	
250	#if (CSC_FEATURES & CSC_FEATURE_MULTIPLE_SENSOR_LOC)
251	    /* In case of supported locations request append locations list */
252	    if (op_code == SC_CP_OP_REQ_SUPPORTED_SENSOR_LOCATIONS){
