{"content": "/* GATT server.
 *
 * Services presented:
 *   0x1816 CSC     - a cadence-only sensor: crank revolution data, no wheel data
 *   0x180F Battery - the liveness probe target of CSC-only clients
 *   0x180A Device Information
 */
#include "gatt_csc.h"

#include <string.h>

#include "csc_defs.h"
#include "csc_sim.h"
#include "esp_log.h"
#include "host/ble_gatt.h"
#include "host/ble_hs.h"
