    {
      s_scan_burst_req       = false;
      s_scan_burst_until_ms  = now_ms + SENSOR_SCAN_BURST_MS;
      g_reconnect_gap_ms     = 0;      /* 空扫退避清零 */
      s_connect_fails        = 0;      /* 连接失败退避清零 */
